s borders.","angle":"entry","strength":"moderate","evidence":["Services exports $518.0bn against GDP $5050.9bn in 2025"]},{"headline":"Early signal: cocoa & cocoa preparations","detail":"Not a headline product yet, but growing 31% a year. Categories that hold that rate tend to reprice the market before they show up in the top ten, which is the window where entry is cheapest.","angle":"timing","strength":"watch","evidence":["Agriculture & food: growing 31% a year since 2022, now 0.70% of imports at rank 28. Growth has been steady rather than a single spike."]}]','2026-09-04 23:36:03'),('res_92d4f9232ce34b4da8b735','ent_nigeria','run_7586e7633b974979adbcc2','overview','{"year":2025,"export_usd":56063265928.563,"import_usd":44354013636.384,"balance_usd":11709252292.179,"total_trade_usd":100417279564.947,"export_yoy_pct":7.06922251497797,"import_yoy_pct":8.265831842658823,"export_concentration":0.7415852368301891,"partner_count":181,"product_count":96,"services_export_usd":5055337924.91534,"services_import_usd":19635280234.4017,"data_sources":["un-comtrade","world-bank"],"coverage_note":null}','2026-09-04 23:37:25'),('res_0ff1438ffddc400192c3f9','ent_nigeria','run_7586e7633b974979adbcc2','top_exports','[{"rank":1,"code":"27","name":"Mineral fuels & oils","value_usd":48160498296.508,"share_pct":85.90384006146449,"cagr_3y":-5.756780957828111,"yoy_pct":3.7930900016815388},{"rank":2,"code":"18","name":"Cocoa & cocoa preparations","value_usd":2368251851.585,"share_pct":4.2242488238244835,"cagr_3y":51.53479469489468,"yoy_pct":23.17517136197627},{"rank":3,"code":"31","name":"Fertilisers","value_usd":2172380632.468,"share_pct":3.8748734960179005,"cagr_3y":4.177336205780713,"yoy_pct":155.4661430021188},{"rank":4,"code":"89","name":"Ships & boats","value_usd":711200076.229,"share_pct":1.2685669742023244,"cagr_3y":-2.807788764218977,"yoy_pct":11.274156270321017},{"rank":5,"code":"08","name":"Fruit & nuts","value_usd":533893656.111,"share_pct":0.952305662662035,"cagr_3y":29.1826377